// brainKnowledge.js — keeps the AI Brain's knowledge base in step with
// portfolio.js.
//
// The Brain used to carry its own hand-written copy of every project and job,
// which drifted: new projects (CAMSCode, IDP, OpsPilot, RoomFlow, …) never
// reached it and the current role was two titles out of date. portfolio.js is
// now the source of truth for WHICH projects/jobs exist and their current
// facts; the hand-written entries only contribute extra colour (impact
// numbers, challenges, business value) where they still line up.

import { projects, experience } from "../../portfolio";

const clean = (s = "") =>
  String(s)
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, "")
    .replace(/^[\s⚡•-]+/, "")
    .replace(/\s+/g, " ")
    .trim();

const shortName = (name) =>
  clean(name)
    .split(/\s+[—–-]\s+/)[0]
    .trim();

// Hand-written Brain id → portfolio slug, for entries that still describe the
// same project. Brain-only projects (not on the site) are kept as they are.
const BRAIN_TO_SLUG = {
  "camslens-enterprise-genai": "cams-lens",
  "sebi-pan-extraction": "sebi-debarred-pan-extraction",
  "financial-email-automation": "ai-email-automation",
  "stock-exchange-platform": "stock-exchange-platform",
  "borderless-table-recognition": "table-recognition-system",
  "ravi-accessibility": "ravi-visual-assistant",
  "driver-drowsiness-detection": "driver-drowsiness-detection",
  "nexgen-gaming-ecommerce": "nexgengaming-ecommerce",
  "ipo-monitoring-notifier": "ipo-monitoring-system",
  "rss-feed-downloader": "rss-document-downloader",
  "msg-to-pdf-converter": "msg-to-pdf-converter",
  "pdf-footnotes-processor": "pdf-footnotes-processor",
  "field-extraction-ocr": "ocr-field-extraction",
  "live-snapshot-restore-vm": "vm-snapshot-system",
  "airline-dbms": "skyline-airlines-dbms",
  "large-file-download": "bittorrent-file-transfer",
  "pacman-multiagent": "ai-pacman-multi-agent-search",
  "lift-controller": "smart-lift-controller",
};

// Hand-written work entry id → "title @ company" in portfolio.js
const WORK_MATCH = {
  "cams-sde": /AI Engineer @ CAMS Mutual Funds/,
  "eamvey-intern": /@ Eamvey Technologies/,
  "iit-delhi-ta": /Teaching Assistant/,
};

const AI_HINT = /\b(ai|ml|llm|gemini|gpt|rag|agent|langgraph|vertex|nlp|vision|ocr|pytorch|tensorflow|opencv|embedding|dialogflow|machine learning)\b/i;

const flattenTech = (p) => {
  const fromBadges = (p.languages || []).map((l) => l.name);
  const ts = p.details?.techStack;
  const fromDetails = Array.isArray(ts)
    ? ts
    : ts && typeof ts === "object"
    ? Object.values(ts).flat()
    : [];
  return [...new Set([...fromBadges, ...fromDetails].map(clean))].filter(
    Boolean
  );
};

const asList = (v) =>
  Array.isArray(v) ? v.map(clean).filter(Boolean) : v ? [clean(v)] : [];

const fromPortfolioProject = (p, hand = {}) => {
  const d = p.details || {};
  const techStack = flattenTech(p);
  const detailed = [d.problem, d.solution].filter(Boolean).map(clean).join(" ");
  return {
    ...hand,
    id: p.slug,
    slug: p.slug,
    name: shortName(p.name),
    fullName: clean(p.name),
    url: p.url || hand.url,
    category:
      hand.category ||
      (AI_HINT.test(`${p.name} ${techStack.join(" ")}`)
        ? "AI/ML"
        : "Software Engineering"),
    timeline: d.timeline || hand.timeline,
    role: d.role || hand.role,
    team: d.team || hand.team,
    description: clean(p.description) || hand.description,
    detailedDescription: detailed || hand.detailedDescription,
    techStack: techStack.length ? techStack : hand.techStack || [],
    features: asList(d.features).length ? asList(d.features) : hand.features,
    architectureHighlights: asList(d.architectureHighlights),
    achievements: asList(d.impact).length
      ? asList(d.impact)
      : hand.achievements,
    learnings: asList(d.learnings).length
      ? asList(d.learnings).join(" ")
      : hand.learnings,
    source: "portfolio",
  };
};

export const syncProjects = (handWritten = []) => {
  const handBySlug = {};
  const handOnly = [];
  handWritten.forEach((h) => {
    const slug = BRAIN_TO_SLUG[h.id];
    if (slug) handBySlug[slug] = h;
    else handOnly.push({ ...h, source: "brain" });
  });
  const fromSite = (projects?.data || [])
    .filter((p) => p.slug && p.name)
    .map((p) => fromPortfolioProject(p, handBySlug[p.slug]));
  // Two RAVI projects share a short name — fall back to the full title.
  const counts = {};
  fromSite.forEach((p) => (counts[p.name] = (counts[p.name] || 0) + 1));
  fromSite.forEach((p) => {
    if (counts[p.name] > 1) p.name = p.fullName;
  });
  return [...fromSite, ...handOnly];
};

export const syncWorkExperience = (handWritten = []) => {
  const sections = experience?.sections || [];
  const entries = [];
  sections.forEach((section) => {
    if (/intern/i.test(section.title)) {
      // Virtual internships live in `virtualInternships`; only real ones here.
      (section.experiences || [])
        .filter((e) => !/virtual/i.test(e.company))
        .forEach((e) => entries.push({ e, type: "Internship" }));
      return;
    }
    const type = /volunteer/i.test(section.title) ? "Volunteer" : "Full-time";
    (section.experiences || []).forEach((e) => entries.push({ e, type }));
  });

  const used = new Set();
  return entries.map(({ e, type }) => {
    const key = `${e.title} @ ${e.company}`;
    const hand =
      handWritten.find((h) => !used.has(h.id) && WORK_MATCH[h.id]?.test(key)) ||
      {};
    if (hand.id) used.add(hand.id);
    return {
      ...hand,
      id: hand.id || key.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
      company: e.company,
      role: e.title,
      duration: e.duration,
      location: e.location || hand.location,
      type: hand.type || type,
      description: clean(e.description) || hand.description,
      url: e.company_url,
    };
  });
};

/** Overlay portfolio.js facts onto the Brain's knowledge object. */
export const syncBrainWithPortfolio = (knowledge) => {
  const workExperience = syncWorkExperience(knowledge.workExperience);
  const current = workExperience.find((w) => /present/i.test(w.duration));
  return {
    ...knowledge,
    profile: {
      ...knowledge.profile,
      ...(current && {
        title: current.role,
        currentRole: `${current.role} at ${current.company}`,
        company: current.company,
      }),
      profileSummary: experience?.description
        ? clean(experience.description)
        : knowledge.profile?.profileSummary,
    },
    workExperience,
    projects: syncProjects(knowledge.projects),
  };
};

// Prompt-sized view of the knowledge object. The full one carries every
// project's architecture notes and learnings — right for retrieval chunks,
// far too heavy to paste whole into a prompt.
export const knowledgeForPrompt = (k) =>
  JSON.stringify({
    ...k,
    projects: (k.projects || []).map((p) => ({
      name: p.name,
      category: p.category,
      timeline: p.timeline,
      role: p.role,
      description: p.description,
      techStack: (p.techStack || []).slice(0, 10),
      highlights: (p.achievements || []).slice(0, 3),
    })),
  });
