// Every workspace tool's hue, including the ones the hero doesn't show;
// the workspace takes its accent from the active tool.
export const TOOL_HUES = {
  ...Object.fromEntries(HERO_TOOLS.map((t) => [t.id, t.hue])),
  Intelligent: "#c9a15a",
  jobhunt: "#8fb58a",
  architecture: "#9a8cf0",
  lab: "#dd86b4",
  projects: "#d8b25a",
};

// Best tool for a free-text request, or null for an empty one.
export function routeIntent(text) {
  const q = ` ${String(text || "").toLowerCase()} `;
  if (!q.trim()) return null;
  let best = null;
  let bestScore = 0;
  HERO_TOOLS.forEach((t) => {
    const raw = t.keys.reduce((s, k) => (q.includes(k) ? s + (k.length > 4 ? 2 : 1) : s), 0);
    // AI Brain's words ("what", "laxman", "project") turn up in most
    // requests, so it only wins when nothing more specific matches.
    const score = t.id === "brain" ? raw * 0.5 : raw;
    if (score > bestScore) {
      best = t;
      bestScore = score;
    }
  });
  // Anything unrecognised is a question about the work → AI Brain.
  return best || HERO_TOOLS[0];
}

// Small line icons, one per tool.
