import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import * as THREE from "three";
import { HERO_TOOLS, routeIntent, ToolGlyph } from "./heroTools";
import "./HeroRouter.css";

/* ==========================================================
   HERO · PROMPT-FIRST ROUTER
   One screen. A prompt bar over a particle horizon; the seven systems
   sit in a shallow 3D arc beneath it. Whatever is typed (or, while the
   visitor is idle, a demo prompt typing itself) is routed to the tool
   that handles it: that card lifts, a beam runs to it from the bar,
   and a ring of light crosses the horizon in the tool's hue.
   Enter opens the tool with the text prefilled.
   ========================================================== */

const DEMO = [
  "Interview me for a GenAI engineering role",
  "Match Laxman to a Senior GenAI Engineer JD",
  "What has Laxman shipped with RAG?",
  "Fix the failing test in the routes module",
  "Triage a customer email about a missing refund",
  "Research the vector database market and recommend one",
  "Assess Laxman for an AI platform team, pros and cons",
];

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
// Jarvis has its own page; OpsPilot and Research Agent open their live
// apps in a new tab; the rest open in the workspace below.
const STANDALONE = ["jarvis", "opspilot", "research"];
const LIVE_APP = ["opspilot", "research"];
// What Enter will do, per tool.
const enterHint = (t) =>
  t.id === "brain"
    ? "Enter to ask AI Brain now. The answer streams in below"
    : t.id === "skills" || t.id === "agents"
    ? `Enter to open ${t.name} with your request filled in`
    : LIVE_APP.includes(t.id)
    ? `Enter to open the live ${t.name} app in a new tab`
    : STANDALONE.includes(t.id)
    ? `Enter to open ${t.name} on its own page`
    : `Enter to open ${t.name}`;

/* ---------- the particle horizon ---------- */

const VERT = `
  attribute float aRand;
  attribute float aLat;
  uniform float uTime;
  uniform float uPulse;
  uniform float uPulseT;
  uniform float uSize;
  varying float vA;
  varying float vPulse;
  void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    float tw = 0.55 + 0.45 * sin(uTime * 1.3 + aRand * 40.0);
    float rim = smoothstep(0.45, 1.0, aLat);
    float w = exp(-pow((aLat - uPulseT) * 8.0, 2.0)) * uPulse;
    vPulse = w;
    vA = (0.14 + 0.62 * rim) * tw + w * 0.95;
    gl_PointSize = uSize * (1.0 + 1.8 * w) * (0.55 + aRand * 0.9) / -mv.z;
  }
`;
const FRAG = `
  uniform vec3 uBase;
  uniform vec3 uHue;
  uniform float uAlpha;
  varying float vA;
  varying float vPulse;
  void main() {
    float d = length(gl_PointCoord - 0.5);
    if (d > 0.5) discard;
    float a = smoothstep(0.5, 0.0, d);
    vec3 col = mix(uBase, uHue, clamp(0.25 + vPulse * 1.4, 0.0, 1.0));
    gl_FragColor = vec4(col, a * vA * uAlpha);
  }
`;

const applyTheme = (mat, theme) => {
  const light = theme === "light";
  mat.uniforms.uBase.value.set(light ? "#2a2f40" : "#f4eee6");
  mat.uniforms.uAlpha.value = light ? 0.75 : 1;
  mat.blending = light ? THREE.NormalBlending : THREE.AdditiveBlending;
  mat.needsUpdate = true;
};

function useHorizon(canvasRef, hueRef, pulseRef, pointerRef, theme) {
  const matRef = useRef(null);
  const themeRef = useRef(theme);
  themeRef.current = theme;
  // A theme change recolours the points; the scene itself is built once.
  useEffect(() => {
    if (matRef.current) applyTheme(matRef.current, theme);
  }, [theme]);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({ canvas, antialias: false, alpha: true, powerPreference: "high-performance" });
    } catch (e) {
      return undefined; // no WebGL: the CSS glow still carries the hero
    }
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);

    // Dome: points on a hemisphere, denser toward the rim.
    const N = window.innerWidth < 700 ? 7000 : 15000;
    const pos = new Float32Array(N * 3);
    const rnd = new Float32Array(N);
    const lat = new Float32Array(N);
    const R = 6.2;
    for (let i = 0; i < N; i++) {
      const u = 1 - Math.pow(Math.random(), 2.4);
      const th = u * (Math.PI / 2);
      const ph = Math.random() * Math.PI * 2;
      const r = R * (1 + (Math.random() - 0.5) * 0.012);
      pos[i * 3] = r * Math.sin(th) * Math.cos(ph);
      pos[i * 3 + 1] = r * Math.cos(th);
      pos[i * 3 + 2] = r * Math.sin(th) * Math.sin(ph);
      rnd[i] = Math.random();
      lat[i] = u;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    geo.setAttribute("aRand", new THREE.BufferAttribute(rnd, 1));
    geo.setAttribute("aLat", new THREE.BufferAttribute(lat, 1));
    const uniforms = {
      uTime: { value: 0 },
      uPulse: { value: 0 },
      uPulseT: { value: 0 },
      uSize: { value: 30 * renderer.getPixelRatio() },
      uBase: { value: new THREE.Color("#f4eee6") },
      uHue: { value: new THREE.Color(hueRef.current) },
      uAlpha: { value: 1 },
    };
    const mat = new THREE.ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      uniforms,
      transparent: true,
      depthWrite: false,
    });
    applyTheme(mat, themeRef.current);
    matRef.current = mat;
    const dome = new THREE.Points(geo, mat);
    dome.position.set(0, -6.9, 0);
    scene.add(dome);

    // A faint field of stars above it.
    const S = 700;
    const sp = new Float32Array(S * 3);
    const sr = new Float32Array(S);
    const sl = new Float32Array(S);
    for (let i = 0; i < S; i++) {
      sp[i * 3] = (Math.random() - 0.5) * 30;
      sp[i * 3 + 1] = Math.random() * 12 - 2;
      sp[i * 3 + 2] = -6 - Math.random() * 10;
      sr[i] = Math.random() * 0.5;
      sl[i] = 0.2;
    }
    const sgeo = new THREE.BufferGeometry();
    sgeo.setAttribute("position", new THREE.BufferAttribute(sp, 3));
    sgeo.setAttribute("aRand", new THREE.BufferAttribute(sr, 1));
    sgeo.setAttribute("aLat", new THREE.BufferAttribute(sl, 1));
    const stars = new THREE.Points(sgeo, mat);
    scene.add(stars);

    const resize = () => {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      if (!w || !h) return;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      // Narrow screens: pull back so the dome still spans the width.
      camera.position.z = w / h < 1 ? 13 : 9.5;
      camera.updateProjectionMatrix();
    };
    resize();
    // Deferred a frame: resizing inside the observer callback trips the
    // "ResizeObserver loop" warning (and CRA's dev overlay).
    let rz = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(rz);
      rz = requestAnimationFrame(resize);
    });
    ro.observe(canvas);

    let raf = 0;
    let visible = true;
    let last = performance.now();
    const hue = new THREE.Color(hueRef.current);
    const cam = { x: 0, y: 0 };
    const tick = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      uniforms.uTime.value += reduce ? 0 : dt;
      dome.rotation.y += reduce ? 0 : dt * 0.035;
      // hue eases toward the routed tool
      hue.set(hueRef.current);
      uniforms.uHue.value.lerp(hue, 1 - Math.exp(-dt * 4));
      // pulse ring travels crown → rim
      const pr = pulseRef.current;
      if (pr.t0) {
        const x = (now - pr.t0) / 1500;
        uniforms.uPulseT.value = x * 1.15;
        uniforms.uPulse.value = x < 1 ? Math.sin(Math.PI * Math.min(1, x * 1.3)) * 0.9 + 0.1 * (1 - x) : 0;
        if (x >= 1) pr.t0 = 0;
      }
      const p = pointerRef.current;
      cam.x += (p.x * 0.7 - cam.x) * (1 - Math.exp(-dt * 3));
      cam.y += (p.y * 0.35 - cam.y) * (1 - Math.exp(-dt * 3));
      camera.position.x = cam.x;
      camera.position.y = 0.4 - cam.y;
      camera.lookAt(0, -0.6, 0);
      renderer.render(scene, camera);
      raf = visible && !document.hidden ? requestAnimationFrame(tick) : 0;
    };
    const start = () => {
      if (!raf && visible && !document.hidden) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
      start();
    });
    io.observe(canvas);
    document.addEventListener("visibilitychange", start);
    start();

    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
      ro.disconnect();
      cancelAnimationFrame(rz);
      document.removeEventListener("visibilitychange", start);
      geo.dispose();
      sgeo.dispose();
      mat.dispose();
      renderer.dispose();
    };
  }, [canvasRef, hueRef, pulseRef, pointerRef]);
}

/* ---------- the hero ---------- */

export default function HeroRouter({ onOpenTool, theme = "dark" }) {
  const rootRef = useRef(null);
  const canvasRef = useRef(null);
  const inputRef = useRef(null);
  const barRef = useRef(null);
  const cardRefs = useRef({});
  const [text, setText] = useState("");
  const [focused, setFocused] = useState(false);
  const [demoText, setDemoText] = useState("");
  const [hoverId, setHoverId] = useState(null);
  const [beam, setBeam] = useState(null);
  const [vw, setVw] = useState(() => window.innerWidth);
  const [launching, setLaunching] = useState(null);
  useEffect(() => {
    const onResize = () => setVw(window.innerWidth);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  const typing = text.trim().length > 0;
  const idle = !typing && !focused;
  const live = typing ? text : idle ? demoText : "";
  const routed = routeIntent(live);
  const shown = hoverId ? HERO_TOOLS.find((t) => t.id === hoverId) : routed;
  const hue = shown ? shown.hue : "#c87046";

  const hueRef = useRef(hue);
  hueRef.current = hue;
  const pulseRef = useRef({ t0: 0 });
  const pointerRef = useRef({ x: 0, y: 0 });
  useHorizon(canvasRef, hueRef, pulseRef, pointerRef, theme);

  // A new destination: send a ring of light across the horizon.
  const shownId = shown ? shown.id : null;
  useEffect(() => {
    if (shownId) pulseRef.current.t0 = performance.now();
  }, [shownId]);

  // Idle: demo prompts type themselves, route, and clear.
  useEffect(() => {
    if (!idle) return undefined;
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
      setDemoText(DEMO[0]);
      return undefined;
    }
    let alive = true;
    let timer = 0;
    let k = 0;
    const wait = (ms) => new Promise((r) => (timer = setTimeout(r, ms)));
    (async () => {
      await wait(700);
      while (alive) {
        const s = DEMO[k % DEMO.length];
        for (let i = 1; i <= s.length && alive; i++) {
          setDemoText(s.slice(0, i));
          await wait(26 + Math.random() * 34);
        }
        await wait(2300);
        for (let i = s.length; i >= 0 && alive; i -= 3) {
          setDemoText(s.slice(0, Math.max(0, i)));
          await wait(12);
        }
        await wait(380);
        k += 1;
      }
    })();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [idle]);

  // "/" focuses the bar from anywhere on the page.
  useEffect(() => {
    const onKey = (e) => {
      if (e.key !== "/" || e.metaKey || e.ctrlKey) return;
      const tag = (document.activeElement && document.activeElement.tagName) || "";
      if (/INPUT|TEXTAREA|SELECT/.test(tag) || document.activeElement?.isContentEditable) return;
      const r = rootRef.current?.getBoundingClientRect();
      if (!r || r.bottom < 0 || r.top > window.innerHeight) return;
      e.preventDefault();
      inputRef.current?.focus();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Pointer: camera drift for the horizon, tilt for the arc.
  useEffect(() => {
    const el = rootRef.current;
    if (!el || !window.matchMedia?.("(pointer: fine)").matches) return undefined;
    let raf = 0;
    let x = 0;
    let y = 0;
    const loop = () => {
      const p = pointerRef.current;
      x += (p.x - x) * 0.08;
      y += (p.y - y) * 0.08;
      el.style.setProperty("--mx", x.toFixed(4));
      el.style.setProperty("--my", y.toFixed(4));
      raf = Math.abs(p.x - x) + Math.abs(p.y - y) > 0.001 ? requestAnimationFrame(loop) : 0;
    };
    const move = (e) => {
      const r = el.getBoundingClientRect();
      pointerRef.current = {
        x: clamp(((e.clientX - r.left) / r.width) * 2 - 1, -1, 1),
        y: clamp(((e.clientY - r.top) / r.height) * 2 - 1, -1, 1),
      };
      el.style.setProperty("--px", `${e.clientX - r.left}px`);
      el.style.setProperty("--py", `${e.clientY - r.top}px`);
      if (!raf) raf = requestAnimationFrame(loop);
    };
    const leave = () => {
      pointerRef.current = { x: 0, y: 0 };
      if (!raf) raf = requestAnimationFrame(loop);
    };
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerleave", leave);
    return () => {
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerleave", leave);
      cancelAnimationFrame(raf);
    };
  }, []);

  // The beam: from the bar down to the chosen card. Measured after layout;
  // re-measured while the arc is still settling into its new pose.
  const measure = useCallback(() => {
    const root = rootRef.current;
    const bar = barRef.current;
    const card = shownId && cardRefs.current[shownId];
    if (!root || !bar || !card) {
      setBeam(null);
      return;
    }
    const R = root.getBoundingClientRect();
    const b = bar.getBoundingClientRect();
    const c = card.getBoundingClientRect();
    const x1 = b.left + b.width / 2 - R.left;
    const y1 = b.bottom - R.top;
    const x2 = c.left + c.width / 2 - R.left;
    const y2 = c.top - R.top + 4;
    const my = (y1 + y2) / 2;
    setBeam({ d: `M${x1} ${y1} C${x1} ${my} ${x2} ${my} ${x2} ${y2}`, x2, y2 });
  }, [shownId]);
  useLayoutEffect(() => {
    measure();
    const t1 = setTimeout(measure, 260);
    const t2 = setTimeout(measure, 700);
    window.addEventListener("resize", measure);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      window.removeEventListener("resize", measure);
    };
  }, [measure]);

  // A short pulse on the chosen card, then hand over to the host.
  const go = (id, prefill) => {
    setLaunching(id);
    setTimeout(() => {
      setLaunching(null);
      onOpenTool?.(id, prefill);
    }, 320);
  };
  const submit = (e) => {
    e.preventDefault();
    if (!typing) {
      inputRef.current?.focus();
      return;
    }
    go(routed.id, text.trim());
  };

  const n = HERO_TOOLS.length;
  return (
    <section
      ref={rootRef}
      className="hr"
      data-theme={theme}
      style={{ "--h": hue }}
      aria-label="Laxman's AI workspace: ask for anything and it is routed to the right agent"
    >
      <canvas ref={canvasRef} className="hr-canvas" aria-hidden="true" />
      <div className="hr-glow" aria-hidden="true" />
      <div className="hr-torch" aria-hidden="true" />

      <div className="hr-center">
        <p className="hr-eyebrow">
          <i aria-hidden="true" />
          Laxman's AI workspace · open to visitors
        </p>
        <h1 className="hr-title">
          <span className="hr-line">Ask for anything.</span>
          <span className="hr-line hr-line-2">The right agent picks it up.</span>
        </h1>
        <p className="hr-sub">
          Seven AI systems I built and run. Type a request and it's routed to the one that handles it.
        </p>

        <form className={`hr-bar${focused ? " is-focus" : ""}`} ref={barRef} onSubmit={submit}>
          <span className="hr-spark" aria-hidden="true">
            ✦
          </span>
          <div className="hr-field">
            <input
              ref={inputRef}
              value={text}
              onChange={(e) => setText(e.target.value)}
              onFocus={() => setFocused(true)}
              onBlur={() => setFocused(false)}
              aria-label="Describe what you need"
              placeholder={focused ? "Describe what you need…" : ""}
              autoComplete="off"
              spellCheck="false"
            />
            {idle && (
              <span className="hr-ghost" aria-hidden="true">
                {demoText}
                <b className="hr-caret" />
              </span>
            )}
          </div>
          <span className="hr-route" aria-live="polite">
            {shown && live ? (
              <span key={shown.id} className="hr-route-in">
                <span className="hr-route-arrow">→</span> {shown.name}
              </span>
            ) : (
              <kbd>/</kbd>
            )}
          </span>
          <button type="submit" className="hr-go" aria-label={shown ? `Open ${shown.name}` : "Open"}>
            ↵
          </button>
        </form>
        <p className="hr-hint">
          {typing && routed ? enterHint(routed) : "Routed by intent · or pick one below"}
        </p>
      </div>

      <svg className="hr-beam" aria-hidden="true">
        <defs>
          <linearGradient id="hr-beam-g" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={hue} stopOpacity="0" />
            <stop offset="0.35" stopColor={hue} stopOpacity="0.9" />
            <stop offset="1" stopColor={hue} stopOpacity="0.9" />
          </linearGradient>
        </defs>
        {beam && (live || hoverId) && (
          <g key={shownId}>
            <path d={beam.d} className="hr-beam-path" stroke="url(#hr-beam-g)" />
            <path d={beam.d} className="hr-beam-flow" />
            <circle cx={beam.x2} cy={beam.y2} r="3.5" className="hr-beam-dot" />
          </g>
        )}
      </svg>

      <div className="hr-arc-wrap">
        <ul className="hr-arc">
          {HERO_TOOLS.map((t, i) => {
            const a = (i - (n - 1) / 2) * 12.5;
            const rad = (a * Math.PI) / 180;
            const R = clamp(vw * 0.62, 640, 980); // arc radius follows the viewport
            const on = shownId === t.id && (!!live || hoverId === t.id);
            const lift = on ? 1 : 0;
            return (
              <li
                key={t.id}
                ref={(el) => (cardRefs.current[t.id] = el)}
                className={`hr-card${on ? " is-on" : ""}${shownId && (live || hoverId) && !on ? " is-off" : ""}${
                  launching === t.id ? " is-launch" : ""
                }`}
                style={{
                  "--h": t.hue,
                  "--i": i,
                  transform: `translate3d(${Math.sin(rad) * R}px, ${lift * -22}px, ${(Math.cos(rad) - 1) * R + lift * 70}px) rotateY(${-a}deg)`,
                }}
              >
                <button
                  type="button"
                  onClick={() => go(t.id, typing ? text.trim() : "")}
                  onMouseEnter={() => setHoverId(t.id)}
                  onMouseLeave={() => setHoverId(null)}
                  onFocus={() => setHoverId(t.id)}
                  onBlur={() => setHoverId(null)}
                >
                  <span className="hr-card-top">
                    <span className="hr-card-icon">
                      <ToolGlyph id={t.id} size={20} />
                    </span>
                    <span className="hr-card-kind">{t.kind}</span>
                  </span>
                  <span className="hr-card-name">{t.name}</span>
                  <span className="hr-card-desc">{t.desc}</span>
                  <span className="hr-card-go" aria-hidden="true">
                    {on && typing ? "↵ Enter" : STANDALONE.includes(t.id) ? "Open ↗" : "Open →"}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      </div>
    </section>
  );
}
